when.set-body:
@{
          var policy = context.Response.Body.As<JObject>();
          var id = context.Request.MatchedParameters["policyId"];
          var risk = (string)policy["riskCategory"];
          if ((string)policy["policyId"] != id || (risk != "Standard" && risk != "Elevated")) {
            throw new Exception("Provider risk contract mismatch.");
          }
          return new JObject(new JProperty("policyId", id), new JProperty("riskCategory", risk)).ToString();
        }
